function githubPanel(){const config=state.github||{};return `<section class="panel"><div class="card-title"><h2>GitHub 题库版本</h2>${state.installedVersion?`<span class="badge">最近导入 ${esc(state.installedVersion.title)}</span>`:''}</div><p class="muted">配置公开仓库后，读取数据目录中的 index.json。每个版本单独放在同名文件夹；点击版本即可下载、校验并导入，不上传学习记录。</p><div class="form-grid"><label class="field">GitHub 用户名 / 组织<input id="github-owner" value="${esc(config.owner||'')}" placeholder="your-account"></label><label class="field">仓库名<input id="github-repo" value="${esc(config.repo||'')}" placeholder="biochem-banks"></label><label class="field">分支或标签<input id="github-ref" value="${esc(config.ref||'main')}"></label><label class="field">数据目录<input id="github-path" value="${esc(config.path||'data')}"></label></div><div class="row" style="margin-top:16px">${btn(catalogLoading?'正在读取…':'保存并读取版本','load-catalog',catalogLoading?'disabled':'')}${btn('下载版本索引模板','catalog-template','',true)}</div><p class="tiny">仓库尚未建立时，可先下载模板。请保持题库为公开可读；无需填写密码或访问令牌。版本导入会合并题目，相同 ID 更新；想完全切换题库，可先备份并清空，再导入。</p>${catalogView?`<div class="catalog-versions">${catalogView.versions.length?catalogView.versions.map(v=>`<div class="version-row"><div><h3>${esc(v.title)}</h3><p class="tiny">${esc(v.id)} · ${v.files.length} 个文件</p><p class="muted">${esc(v.description)}</p></div>${btn('一键导入','import-version',`data-version="${v.id}" ${catalogLoading?'disabled':''}`)}</div>`).join(''):'<p>索引有效，暂无可导入版本。</p>'}</div>`:''}</section>`;}
