actions['persist-storage']=async()=>{try{toast(await navigator.storage?.persist?.()?'已请求持久保存；仍建议定期导出学习备份':'浏览器未授予持久存储，请定期导出学习备份');}catch(_){toast('此浏览器不支持持久存储申请，请定期导出备份');}};
actions['save-daily-settings']=()=>{const raw=$('#daily-days').value.trim(),days=raw===''?null:Number(raw),automatic=$('#daily-auto').checked,target=Number($('#daily-target').value);if(days!==null&&(!Number.isInteger(days)||days<0||days>3650))throw Error('考试剩余天数须为0–3650的整数');if(!automatic&&(!Number.isInteger(target)||target<1||target>10000))throw Error('每天目标须为1–10000的整数');state.settings.examDate=days===null?'':E.dateAfter(days);state.settings.dailyMode=automatic?'auto':'manual';if(!automatic)state.settings.dailyTarget=target;persist();closeModal();render();toast('今日练习设置已保存');};
actions['evaluation-unrestricted']=()=>{state.settings.scopeExplicit=false;state.settings.examTopics=[];resetPracticeForSettings();persist();closeModal();render();toast('已取消章节限制，练习全部章节');};
actions['select-questions-all']=()=>{selectedQuestionIds=new Set(currentQuestionList().map(q=>q.id));updateQuestionSelection();};
actions['select-questions-none']=()=>{selectedQuestionIds.clear();updateQuestionSelection();};
actions['delete-one']=el=>confirmDeleteQuestions([el.dataset.id]);
actions['delete-selected']=()=>confirmDeleteQuestions([...selectedQuestionIds]);
actions['confirm-delete-questions']=()=>{const result=E.deleteQuestions(state,bank(),pendingQuestionDeletes);stopAutoImports();state=result.state;selectedQuestionIds.clear();pendingQuestionDeletes=[];persist();closeModal();render();toast(`已删除 ${result.count} 道题目，当前库存 ${bank().length} 题`);};

actions['chapter-review']=el=>{page='library';libraryTab='review';filterTopic=el.dataset.topic;filterType='';search='';libraryLimit=30;selectedQuestionIds.clear();render();window.scrollTo({top:0,behavior:'instant'});};
actions['evaluation-scope']=evaluationScopeDialog;
actions['evaluation-all']=()=>{document.querySelectorAll('[data-evaluation-topic]').forEach(el=>el.checked=true);updateEvaluationCount();};
actions['evaluation-none']=()=>{document.querySelectorAll('[data-evaluation-topic]').forEach(el=>el.checked=false);updateEvaluationCount();};
actions['save-evaluation-scope']=()=>{const selected=[...document.querySelectorAll('[data-evaluation-topic]:checked')].map(el=>el.dataset.evaluationTopic);state.settings.examTopics=selected;state.settings.scopeExplicit=true;resetPracticeForSettings();persist();closeModal();render();toast('考试范围已保存，评估仅使用所选章节');};
actions['confirm-current-scope']=()=>{if(!examScope().length)throw Error('请至少选择一个考试章节');state.settings.examTopics=examScope();state.settings.scopeExplicit=true;resetPracticeForSettings();persist();render();toast('当前考试范围已用于概率评估');};

actions['open-cleanup']=()=>nav('library');
actions['clear-chapters']=clearChapterDialog;
actions['clear-topics-all']=()=>{document.querySelectorAll('[data-clear-topic]:not(:disabled)').forEach(el=>el.checked=true);updateClearTopicCount();};
actions['clear-topics-none']=()=>{document.querySelectorAll('[data-clear-topic]').forEach(el=>el.checked=false);updateClearTopicCount();};
actions['review-clear-chapters']=confirmChapterDialog;
actions['confirm-clear-chapters']=()=>{const result=E.clearTopics(state,bank(),clearChapterTopics);stopAutoImports();state=result.state;clearChapterTopics=[];persist();closeModal();render();toast(`已清除 ${result.count} 道题目，其他章节保留`);};

actions.chapters=()=>{practiceView='chapters';filterTopic='';filterType='';search='';render();window.scrollTo({top:0,behavior:'instant'});};
actions['add-chapter']=addChapter;
actions['save-chapter']=()=>{const name=$('#chapter-name').value.trim();if(!E.validChapter(name))throw Error('请输入1–80字章节名称，不含尖括号和换行');if(topics().includes(name)||E.canonicalTopic(name)!==name)throw Error('该章节已存在，或名称属于旧版章节简称');state.chapters.push(name);persist();closeModal();render();toast('已新增章节：'+name);};
actions['clear-bank']=()=>modal(`<h2>清空题库所有题目？</h2><p class="muted">将删除当前 ${bank().length} 道题目（包括内置题）及全部作答、错题、收藏和模拟记录。教材章节与自定义章节保留。自动题库更新和文件夹导入会关闭，防止题目重新出现。</p><p class="tiny">可先导出备份，之后仍可从文件或 GitHub 重新导入题库。</p><div class="dialog-actions">${btn('导出学习备份','backup','',true)}${btn('取消','close-modal','',true)}${btn('确认清空所有题目','confirm-clear-bank')}</div>`);
actions['confirm-clear-bank']=()=>{stopAutoImports();state=E.clearBank(state);persist();closeModal();render();toast('题库已清空；章节模块保留');};
actions['graduate-plan']=()=>{state.settings.plan=structuredClone(E.GRADUATE_PLAN);state.settings.total=150;state.settings.pass=90;state.settings.minutes=180;state.settings.preset='graduate';persist();render();};
actions['scope-available']=()=>setScope([...new Set(active().map(q=>q.topic))]);
actions['scope-all']=()=>setScope(topics());actions['scope-none']=()=>setScope([]);
actions['load-catalog']=loadCatalog;actions['import-version']=el=>importVersion(el.dataset.version);
actions['catalog-template']=()=>download('index.json',{schemaVersion:1,versions:[{id:'regular-v1',title:'常规复习题库 v1',description:'将题库模板文件放入 data/regular-v1/questions.json',files:['regular-v1/questions.json']},{id:'graduate-v1',title:'考研复习题库 v1',description:'将另一版本放入独立文件夹，保留稳定的题目 ID',files:['graduate-v1/questions.json']}]});

document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();try{await actions[el.dataset.action]?.(el);}catch(err){toast(err.message);}}});
document.addEventListener('toggle',e=>{if(e.target.id==='question-progress'){const session=currentSession();if(session){session.progressOpen=e.target.open;persist();}}},true);
document.addEventListener('input',e=>{const el=e.target;if(el.id==='daily-days')updateDailyPreview();if(el.dataset.fill!==undefined){const s=currentSession(),q=currentQ();s.answers[q.id]||=[];s.answers[q.id][Number(el.dataset.fill)]=el.value;persist();}if(el.id==='written-answer'){const s=currentSession();s.answers[currentQ().id]=[el.value];persist();}if(el.dataset.plan){state.settings.plan[Number(el.dataset.plan)][el.dataset.field]=Number(el.value);$('#subtotal-'+el.dataset.plan).textContent=state.settings.plan[Number(el.dataset.plan)].count*state.settings.plan[Number(el.dataset.plan)].points+'分';$('#plan-total').textContent='题目合计：'+planTotal()+' 分 / 满分 '+state.settings.total+' 分';persist();}if(el.id==='exam-total'){state.settings.total=Number(el.value);$('#full-score-badge').textContent='满分 '+el.value+' 分';$('#pass-mark').max=el.value;$('#plan-total').textContent='题目合计：'+planTotal()+' 分 / 满分 '+el.value+' 分';persist();}if(el.id==='exam-minutes'){state.settings.minutes=Number(el.value);persist();}if(el.id==='pass-mark'){state.settings.pass=Number(el.value);persist();}if(el.id==='assumption'){state.settings.subjective=Number(el.value);$('#assumption-label').textContent=el.value+'%';persist();}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.reviewStats!==undefined){state.settings.includeReviewStats=el.checked;persist();render();if($('#modal').open)predictionDetails();toast(el.checked?'待确认题首次自评已纳入统计':'已恢复仅安全客观题统计，记录保留');}if(el.dataset.autoUpdate!==undefined){state.settings.autoCheckUpdates=el.checked;persist();toast(el.checked?'已开启启动时检查更新':'已关闭启动时检查更新');}if(el.dataset.includeReview!==undefined){state.settings.includeReview=el.checked;resetPracticeForSettings();persist();render();toast(el.checked?'已开启待确认题参考练习；统计口径由独立开关控制':'已切换为仅安全题');}if(el.dataset.selectQuestion){if(el.checked)selectedQuestionIds.add(el.dataset.selectQuestion);else selectedQuestionIds.delete(el.dataset.selectQuestion);updateQuestionSelection();}if(el.id==='daily-auto')updateDailyPreview();if(el.dataset.evaluationTopic)updateEvaluationCount();if(el.dataset.clearTopic)updateClearTopicCount();if(el.id==='topic-filter'){filterTopic=el.value;selectedQuestionIds.clear();if(page==='practice'&&!filterTopic)practiceView='chapters';render();}if(el.dataset.examTopic){const selected=new Set(examScope());if(el.checked)selected.add(el.dataset.examTopic);else selected.delete(el.dataset.examTopic);state.settings.examTopics=[...selected];state.settings.scopeExplicit=true;resetPracticeForSettings();persist();render();}if(el.id==='type-filter'){filterType=el.value;selectedQuestionIds.clear();render();}if(el.id==='assumption')render();if(el.dataset.examSelf){let score=Number(el.value),max=Number(el.dataset.max);if(!el.value.trim()||score<0||score>max){toast('请输入0到'+max+'之间的分数');return;}const q=byId(el.dataset.examSelf),old=state.exam.selfScores[q.id];state.exam.selfScores[q.id]=score/max;if(old===undefined)E.record(state,q,score/max,true);else E.reviseSelfScore(state,q,score/max);persist();render();}if(el.id==='import-file'){await loadFiles([...el.files]);el.value='';}if(el.id==='restore-file'){try{const b=JSON.parse(await el.files[0].text());if(b.app!=='biochem-practice'||b.version!==1||!b.state?.records||!Array.isArray(b.state?.custom))throw Error('不是有效的学习备份');const v=b.state.custom.length?E.validateBank(b.state.custom,b.state.chapters||[]):{errors:[]};if(v.errors.length)throw Error('备份题库校验失败');window.pendingRestore=b.state;modal(`<h2>恢复学习备份？</h2><p class="muted">备份时间：${esc(b.savedAt)}。将覆盖当前设备的题库、学习记录与设置。</p><div class="dialog-actions">${btn('取消','close-modal','',true)}${btn('确认恢复','confirm-restore')}</div>`);}catch(err){toast('恢复失败：'+err.message);}el.value='';}});
actions['confirm-restore']=()=>{bankEpoch++;state=E.syncSeed(E.migrate(window.pendingRestore),SEED_BANK).state;window.pendingRestore=null;persist();closeModal();render();toast('学习备份已恢复');};
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){const value=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{search=value;selectedQuestionIds.clear();const pos=e.target.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);},280);}});
function updateTimer(){const ex=state.exam;if(!ex||ex.graded)return;const left=Math.max(0,Math.ceil((ex.deadline-Date.now())/1000)),el=$('#exam-timer');if(el)el.textContent=`${String(Math.floor(left/3600)).padStart(2,'0')}:${String(Math.floor(left/60)%60).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(left===0){submitExam(true);toast('模拟考试时间已到，已自动交卷');}}
function updateConnection(){const native=!!window.NativeBridge||location.protocol==='file:';$('#connection').textContent=!storageOK?'保存异常，请备份':!navigator.onLine?'离线练习中':native?'离线题库 · 本机保存':navigator.serviceWorker?.controller?'离线已就绪':'本机保存';}
window.addEventListener('online',updateConnection);window.addEventListener('offline',updateConnection);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false;});
$('#install').hidden=P.native||(!P.ios()||P.standalone());$('#install').onclick=installApplication;
if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol)){
 navigator.serviceWorker.addEventListener('controllerchange',()=>{updateConnection();if(refreshForUpdate)location.reload();});
 navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).then(reg=>{
  webRegistration=reg;function ready(){if(reg.waiting){webUpdateReady=true;if(page==='settings')render();toast('网页新版已就绪，可到设置中更新');}}
  ready();reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)ready();});});
  return navigator.serviceWorker.ready;
 }).then(updateConnection).catch(()=>{});
}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
setInterval(updateTimer,1000);setInterval(()=>{if(!document.hidden){if(pendingAutoFiles.length&&!state.practice&&(!state.exam||state.exam.graded)){const pending=pendingAutoFiles;pendingAutoFiles=[];loadFiles(pending,true);}scanFolder();}},30000);setInterval(()=>{if(!document.hidden)remoteUpdate();},300000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateTimer();updateConnection();}});
render();if(seedUpdate.changed)persist();updateConnection();if(seedUpdate.sessionClosed)toast('新版题库已载入，已结束含旧版题目的练习或模拟卷；历史记录仍保留在本机备份中。');if(!storageOK)toast('无法读取本机数据，请检查存储权限。');if(state.exam&&!state.exam.graded)toast('有一份进行中的模拟卷，计时仍在继续。');setTimeout(remoteUpdate,1000);
if(window.DesktopBridge?.onFiles)DesktopBridge.onFiles(async files=>{if(state.settings.folderAuto===false)return;const local=files.map(f=>new File([Uint8Array.from(atob(f.base64),c=>c.charCodeAt(0))],f.name));await loadFiles(local,true);if(page==='library')render();});

setTimeout(()=>{if(state.settings.autoCheckUpdates&&!state.practice&&(!state.exam||state.exam.graded))checkAppUpdate(true);},2500);
